class Solution {
public:
    vector<int> queryResults(int limit, vector<vector<int>>& queries) {
        unordered_map<int, int> ball_to_color;
        unordered_map<int, int> color_freq;
        vector<int> ans;
        ans.reserve(queries.size());
        for (const auto& q : queries) {
            int x = q[0], y = q[1];
            if (ball_to_color.count(x)) {
                int old = ball_to_color[x];
                if (--color_freq[old] == 0) {
                    color_freq.erase(old);
                }
            }
            ball_to_color[x] = y;
            color_freq[y]++;
            ans.push_back(color_freq.size());
        }
        return ans;
    }
};

class Solution {
    public int[] queryResults(int limit, int[][] queries) {
        Map<Integer, Integer> ballToColor = new HashMap<>();
        Map<Integer, Integer> colorFreq = new HashMap<>();
        int[] ans = new int[queries.length];
        for (int i = 0; i < queries.length; ++i) {
            int x = queries[i][0], y = queries[i][1];
            if (ballToColor.containsKey(x)) {
                int old = ballToColor.get(x);
                int cnt = colorFreq.get(old) - 1;
                if (cnt == 0) colorFreq.remove(old);
                else colorFreq.put(old, cnt);
            }
            ballToColor.put(x, y);
            colorFreq.put(y, colorFreq.getOrDefault(y, 0) + 1);
            ans[i] = colorFreq.size();
        }
        return ans;
    }
}

var queryResults = function(limit, queries) {
    const ballToColor = new Map();
    const colorFreq = new Map();
    const ans = [];
    for (const [x, y] of queries) {
        if (ballToColor.has(x)) {
            const old = ballToColor.get(x);
            const cnt = colorFreq.get(old) - 1;
            if (cnt === 0) colorFreq.delete(old);
            else colorFreq.set(old, cnt);
        }
        ballToColor.set(x, y);
        colorFreq.set(y, (colorFreq.get(y) || 0) + 1);
        ans.push(colorFreq.size);
    }
